import pathlib,socket,subprocess,threading,http.server,time,os,contextlib,secrets,yaml,http.client
root=pathlib.Path.cwd();token=secrets.token_hex(8)
class Backend(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path=='/health':
            self.server.checks+=1;status=200 if self.server.healthy else 503;body=b'health'
        else:self.server.visits+=1;status=200;body=(self.server.label+':'+token).encode()
        self.send_response(status);self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
    def log_message(self,*args):pass
