        config={'global':{'checkNewVersion':False,'sendAnonymousUsage':False},'entryPoints':{'web':{'address':f'127.0.0.1:{port}'}},'providers':{'file':{'filename':str(root/'rendered.yaml'),'watch':False}},'log':{'level':'ERROR'}}
        (root/'traefik.yaml').write_text(yaml.safe_dump(config))
        with (root/'native.log').open('w') as log:
