with fixture() as (get,servers,proc):
    pid=proc.pid
    def wait_for(predicate):
        deadline=time.monotonic()+4
        while not predicate():
            assert time.monotonic()<deadline,'pool state did not converge';time.sleep(.05)
    def batch():return [get('service.lab.test') for _ in range(8)]
    a=(200,('A:'+token).encode());b=(200,('B:'+token).encode())
    wait_for(lambda:set(batch())=={a,b})
    wait_for(lambda:all(server.checks>0 for server in servers))
    servers[1].healthy=False
    wait_for(lambda:set(batch())=={a})
    assert set(batch())=={a},'unhealthy B still receives application traffic'
    # Its ordinary endpoint still returns 200: checking '/' instead of '/health' must fail.
    assert servers[1].visits>0
    servers[1].healthy=True
    wait_for(lambda:set(batch())=={a,b})
    servers[0].healthy=False;servers[1].healthy=False
    wait_for(lambda:all(status==503 for status,_ in batch()))
    assert all(status==503 for status,_ in batch()),'no healthy backend must fail closed'
    servers[0].healthy=True
    wait_for(lambda:set(batch())=={a})
    assert proc.pid==pid and proc.poll() is None,'do not restart entrypoint to fake health recovery'
